Fetch-Data-from-Email.body:
fn((state) => {
  // Define constants
  //const QUERY = 'from:georgemcguire99@gmail.com';
  const QUERY = 'has:attachment';
  const MAX_RESULTS = 1;

// Single step: Query for messages with all two attachment types at once
  return getContentsFromMessages({
    query: QUERY,
    contents: [
      { type: 'file', name: "metadata", file: /^(?!.*(?:DATA|SYNC)).*\.json$/ },
      { type: 'file', name: "fridgeTag", file: /\.txt$/ }
    ],
    maxResults: MAX_RESULTS
  })(state)
  .then((resultState) => {
    // Process results to find messages with all required attachments
    // Filter only messages that have both required properties for the Varo adaptor
    const varoReadyMessages = resultState.data
      .filter(msg => msg?.metadata?.content && msg?.fridgeTag?.content)
      .map(msg => {
        // Return the exact structure expected by Varo adaptor
        return {
          metadata: {
            content: msg.metadata.content,
            filename: msg.metadata.filename
          },
          fridgeTag: {
            content: msg.fridgeTag.content,
            filename: msg.fridgeTag.filename
          },
          messageId: msg.messageId
        };
      });

    // Log the number of valid messages for Varo
    console.log(`Found ${varoReadyMessages.length} messages ready for Varo processing`);

    // Set state.data to be the array of messages in Varo-compatible format
    return { 
      ...resultState,
      data: varoReadyMessages
    };
  });
});

