Data-Transformation-and-Mapping.body:
fn(state => {

  const { data, reports } = state;
  const { trackedEntityInstances } = data

  const trackedEntityPayload = {
    trackedEntities: [],
    events: []
  }
  reports.forEach(report => {
    let orgUnit = ''
    const enrolledAt = new Date().toISOString();
    const matches = trackedEntityInstances.filter(instance => {
      const attrs = instance.enrollments?.[0]?.attributes || [];
      orgUnit = instance.orgUnit
      return attrs.some(attr => instance.trackedEntityType === "R3gvyQLmyX8" && attr.value === report.LSER);
    });

    const commonAttributes = [
      { attribute: "XHdkwj2Gzi8", value: report.LSER },
      { attribute: "juBTPqs6hyQ", value: report.AMOD },
      { attribute: "Dm1zMbsU05X", value: report.AMFR }
    ];

    const minutesToHHMM = mins => {
      if (mins == null || isNaN(mins)) return "";
      // Cap at 23:59 if minutes >= 1440
      if (mins >= 1440) return "23:59";
      const h = Math.floor(mins / 60);
      const m = Math.round(mins % 60);
      return `${h.toString().padStart(2, "0")}:${m.toString().padStart(2, "0")}`;
    };


    const events = report.reports.map(subReport => {
      const aggregates = subReport.aggregates?.[0] || {};
      const alarmCondition = subReport.alarms?.[0]?.condition;
      const alarmMinutes = subReport.alarms[0]?.conditionMinutes;

      return {
        program: "EThvOOPdWdU",
        programStage: "QfEdltht9gW",
        status: "ACTIVE",
        enrolledAt: enrolledAt,
        occurredAt: subReport.date,
        dataValues: [
          {
            dataElement: "ITjXBXe4LHp",
            value: String(aggregates.average || ''),
          },
          {
            dataElement: "lMGgg93GNCj",
            value: 
              (alarmCondition === "HEAT" && alarmMinutes > 600) ||
              (alarmCondition === "FREEZE" && alarmMinutes > 60)
                ? "ALARM"
                : "ok"
          },
          {
            dataElement: "iMon5EnL5tT",
            value: String(aggregates.min || '')
          },
          {
            dataElement: "uKw4f9GjumZ", 
            value: alarmCondition === 'HEAT' ? minutesToHHMM(alarmMinutes) : "00:00"
          },
          {
            dataElement: "ZkLhYyo0muJ", 
            value: alarmCondition === 'FREEZE' ? minutesToHHMM(alarmMinutes) : "00:00"
          },
          {
            dataElement: "pXXv6fqYhhx",
            value: String(aggregates.max || ''),
          },
          {
            dataElement: "YBjvNW66Q78",
            value: subReport.alarms[0]?.condition,
          }
        ],
      }
    });

    if (matches.length > 0) {
      matches.forEach(match => {
        trackedEntityPayload.trackedEntities.push({
          orgUnit: match.orgUnit,
          program: "EThvOOPdWdU",
          programStage: "QfEdltht9gW",
          trackedEntityType: "R3gvyQLmyX8",
          attributes: commonAttributes,
          trackedEntityInstance: match.trackedEntity,
          trackedEntity: match.trackedEntity,
        });

      const entityEvents = events.map(event => {
      const existingEvent = match.enrollments[0].events
        .find(e =>
          e.occurredAt && event.occurredAt &&
          new Date(e.occurredAt).toISOString().slice(0,10) ===
          new Date(event.occurredAt).toISOString().slice(0,10)
        );
      return {
        ...event,
        event: existingEvent ? existingEvent.event : null,
        enrollment: match.enrollments[0].enrollment,
        orgUnit: match.orgUnit,
      };
      });

        trackedEntityPayload.events.push(...entityEvents);
      })
    } else {
      console.log("orgunit", orgUnit)
      trackedEntityPayload.trackedEntities.push({
        orgUnit: orgUnit,
        program: "EThvOOPdWdU",
        programStage: "QfEdltht9gW",
        attributes: commonAttributes,
        enrollments: [
          {
            program: "EThvOOPdWdU",
            orgUnit: "FV43JisquSm",
            enrolledAt: enrolledAt,
            occurredAt: enrolledAt,
            events: events.map(event => ({
              ...event,
              orgUnit: orgUnit
            }))
          }
        ]
      })
    }
  })

  return { trackedEntityPayload, ...state }
})

