fn(state => {
  const { codes = [] } = state.data;
  const payload = state.trackedEntityPayload;

  payload.trackedEntities = payload.trackedEntities.map(trackedEntity => {
    const isNew = !trackedEntity.trackedEntityInstance;

    // Assign new trackedEntityInstance ID if needed
    const trackedEntityInstance = isNew ? codes.shift() : trackedEntity.trackedEntityInstance;

    if (isNew) {
      // Only new tracked entities have enrollments
      const enrollments = trackedEntity.enrollments.map(enrollment => {
        const events = enrollment.events.map(event => ({
          ...event,
          event: event.event || codes.shift()
        }));

        const processedEnrollment = {
          ...enrollment,
          enrollment: codes.shift(),
          events,
        };
        delete processedEnrollment.trackedEntity; // DHIS2 doesn't want trackedEntity in enrollment
        return processedEnrollment;
      });

      return {
        ...trackedEntity,
        trackedEntityInstance,
        trackedEntityType: "R3gvyQLmyX8",
        enrollments,
      };
    } else {
      // Existing tracked entities: don't touch enrollments
      return {
        ...trackedEntity,
        trackedEntityInstance,
        trackedEntityType: trackedEntity.trackedEntityType,
      };
    }
  });

  state.trackedEntityPayload = payload;
  return state;
})


